// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

class FrontierJoinProgramTest {

	@Test
	void variableClassesAreCompactAndCannotDriveUnboundedScratch() {
		FrontierLeafProbe[] patterns = { predicateProbe(1L, 0), predicateProbe(2L, 0) };
		int[] sparseClasses = {
				Integer.MAX_VALUE, 0, 0, 0,
				1, 0, 0, 0
		};

		assertThrows(IllegalArgumentException.class, () -> new FrontierJoinProgram(patterns, sparseClasses));
	}

	@Test
	void repeatedVariablesMustMatchTheLeafEqualityContract() {
		int subjectObject = FrontierLeafProbe.SUBJECT_OBJECT_EQUAL;
		int[] variableClasses = {
				1, 0, 1, 0,
				1, 0, 2, 0
		};

		assertThrows(IllegalArgumentException.class, () -> new FrontierJoinProgram(
				new FrontierLeafProbe[] { predicateProbe(1L, 0), predicateProbe(2L, 0) }, variableClasses));
		assertDoesNotThrow(() -> new FrontierJoinProgram(
				new FrontierLeafProbe[] { predicateProbe(1L, subjectObject), predicateProbe(2L, 0) },
				variableClasses));
	}

	@Test
	void repeatedEqualityOnBoundComponentsDoesNotRequireAVariableClass() {
		FrontierLeafProbe boundSelfLoop = new FrontierLeafProbe(FrontierLeafProbe.BOTH_PLANES,
				FrontierLeafProbe.SUBJECT | FrontierLeafProbe.PREDICATE | FrontierLeafProbe.OBJECT
						| FrontierLeafProbe.CONTEXT,
				7L, 1L, 7L, 0L, FrontierLeafProbe.SUBJECT_OBJECT_EQUAL);
		int[] noVariableClasses = new int[2 * FrontierOmniLayout.COMPONENT_COUNT];

		assertDoesNotThrow(() -> new FrontierJoinProgram(
				new FrontierLeafProbe[] { boundSelfLoop, predicateProbe(2L, 0) }, noVariableClasses));
	}

	private static FrontierLeafProbe predicateProbe(long predicate, int repeatedComponentPairMask) {
		return new FrontierLeafProbe(FrontierLeafProbe.BOTH_PLANES, FrontierLeafProbe.PREDICATE,
				0L, predicate, 0L, 0L, repeatedComponentPairMask);
	}
}
